import{g as a,ae as e,r as n,B as t}from"./chunks/framework.CZ-ntRvv.js";const _=JSON.parse('{"title":"Composables","description":"","frontmatter":{},"headers":[],"relativePath":"docs/other/composables.md","filePath":"docs/other/composables.md","lastUpdated":1790261415000}'),p={name:"docs/other/composables.md"};function o(c,s,l,d,i,r){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="composables" tabindex="-1">Composables <a class="header-anchor" href="#composables" aria-label="Permalink to “Composables”">​</a></h1><p>Composition API helpers that don&#39;t belong to one component: page title, color scheme, shell scrolling and keyboard shortcuts.</p><h2 id="usepagemeta" tabindex="-1">usePageMeta <a class="header-anchor" href="#usepagemeta" aria-label="Permalink to “usePageMeta”">​</a></h2><p>Keeps <code>document.title</code> and the favicon in sync with reactive state. Call it once per page component. It watches the function you pass and applies the result again whenever a dependency changes.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">ref</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">usePageMeta</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> title</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> ref</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Loading…</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"></span>
<span class="line"><span class="s_indoxt">usePageMeta</span><span class="s_13ahmt">(()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span></span>
<span class="line"><span class="s_r4oegk">  title</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> title</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  emoji</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">🌈</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}))</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>The function returns <code>null</code> or <code>undefined</code> to skip an update, or a <code>PageMeta</code> object:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td><code>string</code></td><td>Sets <code>document.title</code>.</td></tr><tr><td><code>icon</code></td><td><code>string</code></td><td>URL of a favicon image.</td></tr><tr><td><code>emoji</code></td><td><code>string</code></td><td>Uses the emoji as the favicon. Wins over <code>icon</code>.</td></tr></tbody></table><p>With neither <code>icon</code> nor <code>emoji</code>, the page&#39;s original favicon comes back.</p><p>Inside a component, the watcher stops on unmount, so there is nothing to clean up. <code>usePageMeta</code> also returns a stop function, for calls outside a component such as a router hook or a plain module:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> stop</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> usePageMeta</span><span class="s_13ahmt">(()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span><span class="s_r4oegk"> title</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Loading…</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }))</span></span>
<span class="line"><span class="s_1th9sy">// later</span></span>
<span class="line"><span class="s_indoxt">stop</span><span class="s_13ahmt">()</span></span></code></pre></div><h2 id="usecolorscheme" tabindex="-1">useColorScheme <a class="header-anchor" href="#usecolorscheme" aria-label="Permalink to “useColorScheme”">​</a></h2><p>Reads and sets the app&#39;s light or dark preference. Every caller shares one state. The first call restores the saved preference and starts following the OS setting, so there is nothing to install.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useColorScheme</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_1jjt6x"> {</span><span class="s_295sjd"> colorScheme</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> resolvedColorScheme</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> setColorScheme</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> toggleColorScheme</span><span class="s_1jjt6x"> }</span><span class="s_2ekfrt"> =</span></span>
<span class="line"><span class="s_indoxt">  useColorScheme</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">button</span><span class="s_1i4ay4"> @click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">toggleColorScheme</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">    {{ resolvedColorScheme === &#39;dark&#39; ? &#39;Light mode&#39; : &#39;Dark mode&#39; }}</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_1uuh8p">button</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Member</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>colorScheme</code></td><td><code>Ref&lt;&#39;light&#39; | &#39;dark&#39; | &#39;system&#39;&gt;</code></td><td>The selected preference. Read-only: change it with <code>setColorScheme</code>, which also updates <code>&lt;html data-theme&gt;</code> and the saved value.</td></tr><tr><td><code>resolvedColorScheme</code></td><td><code>Ref&lt;&#39;light&#39; | &#39;dark&#39;&gt;</code></td><td>The scheme on screen. Under <code>system</code> it follows the OS. Read this for a sun or moon icon, or an image per scheme.</td></tr><tr><td><code>setColorScheme(scheme)</code></td><td><code>(scheme) =&gt; void</code></td><td>Selects a preference, sets <code>data-theme</code>, and saves it.</td></tr><tr><td><code>toggleColorScheme()</code></td><td><code>() =&gt; void</code></td><td>Switches to the opposite of what is on screen. Under <code>system</code> on a dark OS it selects <code>light</code>.</td></tr></tbody></table><p>Switching schemes would otherwise animate every element with a CSS transition at the same time, which looks like a flash. To prevent it, <code>useColorScheme</code> adds a <code>no-transition</code> class to <code>&lt;html&gt;</code> for the two frames around the switch. The CSS rule for that class is in <code>frappe-ui/style.css</code>. Apps that don&#39;t load that stylesheet still switch correctly, but with the animation.</p><h2 id="useresolvedcolorscheme" tabindex="-1">useResolvedColorScheme <a class="header-anchor" href="#useresolvedcolorscheme" aria-label="Permalink to “useResolvedColorScheme”">​</a></h2><p>Returns the current <code>&#39;light&#39; | &#39;dark&#39;</code> scheme without setting it. It reads the document and follows changes, and it writes nothing.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useResolvedColorScheme</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> scheme</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useResolvedColorScheme</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">img</span><span class="s_1i4ay4"> :src</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">scheme === &#39;dark&#39; ? darkShot : lightShot</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> alt</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Use it when something else already sets <code>data-theme</code>: an app that sets its own theme before the first paint, a page embedded in another app, or a demo in an iframe. <code>useColorScheme()</code> would be a second writer of that attribute and of the <code>theme</code> storage key, because its first call applies the saved preference.</p><ul><li>It returns <code>Readonly&lt;Ref&lt;&#39;light&#39; | &#39;dark&#39;&gt;&gt;</code> directly, not an object.</li><li>It reads <code>&lt;html data-theme&gt;</code> first, then Tailwind&#39;s <code>dark</code> class, then the OS setting, and reacts to all three.</li><li>It writes no attribute, class or <code>localStorage</code> key, and it does not start <code>useColorScheme</code>&#39;s shared state.</li><li>Outside the browser it returns <code>light</code>.</li></ul><p>When your app owns the scheme, read <code>useColorScheme().resolvedColorScheme</code> instead. It is the same value.</p><h2 id="shellscrollcontainer-useshellscrolled" tabindex="-1">shellScrollContainer / useShellScrolled <a class="header-anchor" href="#shellscrollcontainer-useshellscrolled" aria-label="Permalink to “shellScrollContainer / useShellScrolled”">​</a></h2><p><code>shellScrollContainer</code> is a computed ref to the scroll element of the mounted <a href="./../components/desktopshell"><code>DesktopShell</code> or <code>MobileShell</code></a>, or <code>null</code> when neither is mounted. Read <code>scrollTop</code> from it, or call <code>scrollTo</code> or <code>scrollBy</code>, from anywhere: a component, a <code>vue-router</code> <code>scrollBehavior</code>, or a navigation guard.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">shellScrollContainer</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_50ecpt">function</span><span class="s_indoxt"> scrollToTop</span><span class="s_13ahmt">()</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_22m8k2">  shellScrollContainer</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">?.</span><span class="s_indoxt">scrollTo</span><span class="s_13ahmt">({ </span><span class="s_r4oegk">top</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> 0</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> behavior</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">smooth</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>useShellScrolled</code> returns whether that container is scrolled past a threshold. Use it to show a header border or shadow on scroll. It follows the active shell when the layout switches between desktop and mobile.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useShellScrolled</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> scrolled</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useShellScrolled</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> threshold</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> 12</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">header</span><span class="s_1i4ay4"> :data-scrolled</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">scrolled</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">…</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">header</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>threshold</code> is required, in pixels. It has no default because no single value suits every layout: the old 200px default made header borders appear late.</p><p>The value comes from the nearest shell above the caller. A shell provides its own scroll element to its children, so a page inside one reads that shell even while another shell is still mounted. A caller outside any shell reads the globally registered shell instead.</p><p>Without a mounted shell, <code>scrolled</code> stays <code>false</code> and the composable warns once in development.</p><h2 id="usekeyboardshortcut" tabindex="-1">useKeyboardShortcut <a class="header-anchor" href="#usekeyboardshortcut" aria-label="Permalink to “useKeyboardShortcut”">​</a></h2><p>Registers a global keyboard shortcut while the calling component is mounted. It adds and removes the <code>keydown</code> listener for you, and returns nothing.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useKeyboardShortcut</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_indoxt">useKeyboardShortcut</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  combo</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Mod+K</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  description</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Open command palette</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  group</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">General</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  allowInInput</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">  handler</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> ()</span><span class="s_50ecpt"> =&gt;</span><span class="s_indoxt"> open</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Pass an array to register several at once.</p><h3 id="the-combo" tabindex="-1">The combo <a class="header-anchor" href="#the-combo" aria-label="Permalink to “The combo”">​</a></h3><p>A combo is <code>Mod+Ctrl+Alt+Shift+&lt;Key&gt;</code>. The type requires that order, but the matcher accepts the modifiers in any order.</p><table tabindex="0"><thead><tr><th>Modifier</th><th>Means</th></tr></thead><tbody><tr><td><code>Mod</code></td><td>Cmd on macOS, Ctrl elsewhere</td></tr><tr><td><code>Ctrl</code></td><td>Control on every platform</td></tr><tr><td><code>Alt</code></td><td>Alt, Option on macOS</td></tr><tr><td><code>Shift</code></td><td>Shift</td></tr></tbody></table><p>Digits and punctuation use a key <strong>name</strong>, not the character: <code>Mod+Slash</code>, not <code>Mod+/</code>. <code>+</code> separates the parts, so <code>Mod++</code> would never fire. The names are <code>Digit0</code>–<code>Digit9</code>, <code>Plus</code>, <code>Minus</code>, <code>Equal</code>, <code>Slash</code>, <code>Backslash</code>, <code>Backtick</code>, <code>Comma</code>, <code>Period</code>, <code>Semicolon</code>, <code>Quote</code>, <code>BracketLeft</code>, <code>BracketRight</code>.</p><p><code>Plus</code> is the keypad <code>+</code>. A normal keyboard types <code>+</code> with Shift, so ⌘+ is <code>Mod+Shift+Equal</code>.</p><p>Letters, function keys and named keys (<code>Escape</code>, <code>Enter</code>, <code>Space</code>, <code>ArrowUp</code>, …) match <code>event.key</code>. Digits and punctuation match <code>event.code</code>, so <code>Mod+Shift+Digit1</code> fires on both ⌘⇧1 and ⌘⇧!. A punctuation name means the physical key position on a US layout, so <code>Mod+Slash</code> fires on the same key on every layout. The full grammar is in <a href="https://github.com/frappe/frappe-ui/blob/main/spec/shortcuts.md" target="_blank" rel="noreferrer"><code>spec/shortcuts.md</code></a>.</p><p>TypeScript checks the combo: an unknown key name or a stray character fails to compile. In JavaScript it warns once and never fires.</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>combo</code></td><td><code>KeyboardShortcutCombo</code></td><td>none</td><td>The key combination.</td></tr><tr><td><code>description</code></td><td><code>string</code></td><td>none</td><td>Label in <code>KeyboardShortcutsDialog</code>. Shortcuts with the same label share one row.</td></tr><tr><td><code>group</code></td><td><code>string</code></td><td><code>&quot;General&quot;</code></td><td>Heading the shortcut is listed under.</td></tr><tr><td><code>handler</code></td><td><code>(e) =&gt; void</code></td><td>none</td><td>Runs on keydown. Press mode.</td></tr><tr><td><code>onHold</code></td><td><code>(e) =&gt; void</code></td><td>none</td><td>Runs once when the combo goes down. Hold mode.</td></tr><tr><td><code>onRelease</code></td><td><code>(e?) =&gt; void</code></td><td>none</td><td>Runs when a held combo is released.</td></tr><tr><td><code>enabled</code></td><td><code>MaybeRefOrGetter&lt;boolean&gt;</code></td><td><code>true</code></td><td>While <code>false</code>, the shortcut does nothing <strong>and</strong> is hidden from the dialog.</td></tr><tr><td><code>preventDefault</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Call <code>preventDefault()</code> on the matched event.</td></tr><tr><td><code>allowInInput</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Fire while an input, textarea or contenteditable has focus.</td></tr><tr><td><code>allowInDialog</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Fire while focus is inside a <code>[role=&quot;dialog&quot;]</code> element.</td></tr></tbody></table><p>A shortcut uses either press mode or hold mode. Press mode takes <code>handler</code>. Hold mode takes <code>onHold</code> and usually <code>onRelease</code>, and no <code>handler</code>.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_indoxt">useKeyboardShortcut</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  combo</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Mod+Shift+L</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  description</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Highlight blocks with client scripts</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  group</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">View</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">  onHold</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> ()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">highlight</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_2ekfrt"> =</span><span class="s_40mev6"> true</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">  onRelease</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> ()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">highlight</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_2ekfrt"> =</span><span class="s_40mev6"> false</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span></code></pre></div><p><code>onRelease</code> also runs if the component unmounts, or is deactivated inside a <code>&lt;KeepAlive&gt;</code>, while the combo is still held. Without this, the highlight above would stay on with no shortcut left to turn it off. In that case there is no key event, so <code>onRelease</code> gets no argument: its parameter is optional, and a callback that reads the event must handle <code>undefined</code>.</p><h3 id="two-shortcuts-on-one-combo" tabindex="-1">Two shortcuts on one combo <a class="header-anchor" href="#two-shortcuts-on-one-combo" aria-label="Permalink to “Two shortcuts on one combo”">​</a></h3><p>The last registration that is <strong>enabled at the time of the keypress</strong> wins. <code>enabled</code> is checked first, so two registrations with opposite conditions both work. In development the library warns once per combo, naming the hidden shortcut and the active one.</p><h3 id="showing-them-to-the-user" tabindex="-1">Showing them to the user <a class="header-anchor" href="#showing-them-to-the-user" aria-label="Permalink to “Showing them to the user”">​</a></h3><p><a href="./../components/keyboardshortcutsdialog"><code>KeyboardShortcutsDialog</code></a> shows every registered shortcut as a searchable list. It reads the registry itself, and its default slot gives the grouped shortcuts to an app that wants its own layout.</p>`,49)])])}const u=a(p,[["render",o]]);export{_ as __pageData,u as default};
